#!/bin/bash
# components/fail2ban/component.sh - fail2ban with UFW as the ban action.
#
# Layout (jail.d drop-ins, merged by name):
#   00-default.local    shared defaults (UFW ban action, progressive bans)
#   01-ignoreip.local   GENERATED by update-cloudflare-ips.sh - never edit;
#                       permanent entries go into /etc/fail2ban/ignoreip.custom
#   10-sshd.local       rendered with the SSH port
#   20-nginx.local      nginx jails (only when a scheme puts nginx on the public ports)
#   30-recidive.local   repeat-offender escalation
#
# fail2ban_base belongs to the machine (SSH protection, whatever scheme runs);
# fail2ban_nginx is deployed by schemes that use nginx.

F2B_ASSETS="$VPSAD_ROOT/components/fail2ban"

fail2ban_apply() {
    local changed="$1"
    if [ "$changed" -eq 0 ] && systemctl is-active --quiet fail2ban; then
        return 0
    fi
    if ! fail2ban-client -t >/dev/null 2>&1; then
        fail2ban-client -t || true
        die "fail2ban configuration test failed"
    fi
    systemctl enable --quiet fail2ban
    systemctl restart fail2ban
    local _
    for _ in $(seq 1 20); do
        fail2ban-client ping >/dev/null 2>&1 && return 0
        sleep 0.5
    done
    die "fail2ban did not come up after the restart"
}

fail2ban_base() {
    local ssh_port="$1" f tmp changed=0
    # shellcheck disable=SC2034 # read by render_template through a nameref
    local -A vals=([SSH_PORT]="$ssh_port")
    ensure_packages fail2ban
    command -v ufw >/dev/null || die "ufw not found - the ban action depends on it"
    # A monolithic jail.local from an older deployment would fight the drop-ins.
    if [ -f /etc/fail2ban/jail.local ]; then
        mv /etc/fail2ban/jail.local /etc/fail2ban/jail.local.pre-jaild.bak
        msg_warn "Legacy /etc/fail2ban/jail.local moved to jail.local.pre-jaild.bak"
        changed=1
    fi
    install -d /etc/fail2ban/jail.d
    for f in 00-default.local 30-recidive.local; do
        install_if_changed "$F2B_ASSETS/jail.d/$f" "/etc/fail2ban/jail.d/$f" && changed=1
    done
    tmp="$(mktemp)"
    render_template "$F2B_ASSETS/jail.d/10-sshd.local.template" "$tmp" text vals
    install_if_changed "$tmp" /etc/fail2ban/jail.d/10-sshd.local && changed=1
    rm -f "$tmp"
    fail2ban_apply "$changed"
    msg_ok "fail2ban: sshd (port $ssh_port) and recidive jails active"
}

fail2ban_nginx() {
    local filter logfile changed=0
    for logfile in /nginx/logs/access.log /nginx/logs/error.log; do
        # file-backend jails refuse to start when their logpath is missing
        [ -f "$logfile" ] || { install -d /nginx/logs; touch "$logfile"; }
    done
    for filter in "$F2B_ASSETS"/filter.d/*; do
        install_if_changed "$filter" "/etc/fail2ban/filter.d/$(basename "$filter")" && changed=1
    done
    install_if_changed "$F2B_ASSETS/jail.d/20-nginx.local" /etc/fail2ban/jail.d/20-nginx.local && changed=1
    # The updater owns 01-ignoreip.local; fail2ban never runs without the
    # Cloudflare ranges ignored (banning a CF edge IP cuts all CDN traffic).
    [ -f /etc/fail2ban/jail.d/01-ignoreip.local ] || { cloudflare_ips_update; changed=1; }
    fail2ban_apply "$changed"
    msg_ok "fail2ban jails: $(fail2ban-client status | sed -n 's/.*Jail list:[[:space:]]*//p')"
}

# Single source of truth for Cloudflare ranges: the nginx geo file and the
# fail2ban ignoreip drop-in, refreshed monthly by cron.
cloudflare_ips_update() {
    install -o root -g root -m 700 "$F2B_ASSETS/update-cloudflare-ips.sh" /usr/local/bin/update-cloudflare-ips.sh
    /usr/local/bin/update-cloudflare-ips.sh
    local cron_line="0 3 1 * * /usr/local/bin/update-cloudflare-ips.sh >> /var/log/cf-ip-update.log 2>&1"
    {
        crontab -l 2>/dev/null | grep -v "update-cloudflare-ips" || true
        echo "$cron_line"
    } | crontab -
}
